/// The values a network runs with when a configuration states no flag.
///
/// The build script reads them off the `(easytier.flag)` annotations on the
/// message, in protobuf JSON, and the config UI reads the same annotations
/// from its own bindings, so an unset flag means the same thing on both
/// sides.
pub fn defaults() -> Self {
    static DEFAULTS: OnceLock<Flags> = OnceLock::new();
    DEFAULTS
        .get_or_init(|| {
            serde_json::from_str(flags::DEFAULTS)
                .expect("the build script writes the defaults from the schema")
        })
        .clone()
}

/// Applies `patch` over [`Flags::defaults`]. A field the user left out keeps
